{"content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>
/// Positional CLI syntax for the census: <c>census &lt;trace.jsonl&gt;</c> and
/// <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>. Anything else parses to an empty command,
/// which the runner turns into a usage error and exit 1.
/// </summary>
public static class CommandLineArgumentParser
{
	/// <summary>Parses the positional subcommand and its paths into configuration keys.</summary>
	/// <param name="args">Raw CLI arguments.</param>
	/// <returns>Configuration keys under the <see cref="AutoWrongCensusOptions.SectionName"/> section.</returns>
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 2 && args[0].Equals("census", StringComparison.OrdinalIgnoreCase))
		{
			dict["AutoWrongCensus:Command"] = "census";
			dict["AutoWrongCensus:TracePath"] = args[1];
		}
		else if (args.Length == 3 && args[0].Equals("pairs", StringComparison.OrdinalIgnoreCase))
		{
			dict["AutoWrongCensus:Command"] = "pairs";
			dict["AutoWrongCensus:CensusTsvPath"] = args[1];
			dict["AutoWrongCensus:TracePath"] = args[2];
		}

		return dict;
	}
}
