/// <summary>Usage text for the auto-wrong census CLI.</summary>
public static class AutoWrongCensusUsage
{
	/// <summary>Prints the usage to stdout.</summary>
	public static void Print()
	{
		System.Console.Out.WriteLine("F-428 P12.13 — auto-wrong census");
		System.Console.Out.WriteLine();
		System.Console.Out.WriteLine("usage:");
		System.Console.Out.WriteLine("  LetUsCook.AutoWrongCensus census <trace.jsonl>");
		System.Console.Out.WriteLine("      Classifies every auto-wrong line (auto == true && correct == false) of a");
		System.Console.Out.WriteLine("      HoldoutGate debug/batch trace by relation (accepted row vs key row) and site.");
		System.Console.Out.WriteLine("      TSV on stdout; relation x site summary on stderr.");
		System.Console.Out.WriteLine();
		System.Console.Out.WriteLine("  LetUsCook.AutoWrongCensus pairs <census.tsv> <trace.jsonl>");
		System.Console.Out.WriteLine("      Emits the parsedName head and key head words for every census row with");
		System.Console.Out.WriteLine("      blocker=window and route compound/other, joined to the trace.");
		System.Console.Out.WriteLine();
		System.Console.Out.WriteLine("Exits 1 on a missing file, a trace whose set is not debug or batch (D-029),");
		System.Console.Out.WriteLine("or a malformed invocation.");
	}
}
