{"content":"namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// One classified auto-wrong line: the TSV row plus the stderr-only extras (qualifier diff, tier
/// direction, missing field). TSV column order is the <see cref="ToTsvRow"/> order.
/// </summary>
public sealed record ClassificationResult
{
	/// <summary>Holdout id of the line.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index within the recipe.</summary>
	public int LineIndex { get; init; }

	/// <summary>Trace set (<c>debug</c> or <c>batch</c>).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Relation class: no-label, pack-unit-state, compound-head-lost, state-mismatch, row-choice-tier, same-head-other-qualifier, sibling-food, other.</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>Site: reuse, override, curated, ranker. <see langword="null"/> when the atom's path was unrecognised.</summary>
	public string? Site { get; init; }

	/// <summary>For site=override: <c>yes</c>/<c>no</c> — whether the normalised rawText is a key in exact-overrides.json.</summary>
	public string? OverrideKey { get; init; }

	/// <summary>Dataset tier of the accepted row.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Dataset tier of the key row.</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>Combined state mask of the accepted row (ExtractCandidateState | ExtractCandidateSatisfiers).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Combined state mask of the key row.</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name, verbatim.</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>The key head phrase (head term plus non-state leading tokens), singularised, space-joined.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>The accepted row's description.</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>The key row's description.</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>For same-head-other-qualifier: the qualifier words present on one side only, for the stderr detail.</summary>
	public string? QualifierDiff { get; init; }

	/// <summary>For row-choice-tier: which tier is higher, <c>key</c> or <c>accepted</c>.</summary>
	public string? TierDirection { get; init; }

	/// <summary>For relation=other: the trace field that was missing, when that is why.</summary>
	public string? MissingField { get; init; }

	/// <summary>Whether the resolver's own exact-phrase rule (ShouldReuse) would match parsedName to the linked master; reuse-site lines only.</summary>
	public bool? ShouldReuseMatch { get; init; }

	/// <summary>Renders the TSV row in the contract column order.</summary>
	/// <returns>The tab-joined row.</returns>
	public string ToTsvRow() => string.Join('\t',
		HoldoutId,
		LineIndex.ToString(System.Globalization.CultureInfo.InvariantCulture),
		Set,
		Relation,
		Site ?? string.Empty,
		OverrideKey ?? string.Empty,
		AcceptedTier,
		KeyTier,
		AcceptedState,
		KeyState,
		ParsedName,
		KeyHead,
		AcceptedDesc,
		KeyDesc,
		RawText);
}
