{"content":"using System.Globalization;
using System.Text.Json;
using System.Text.Json.Serialization;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Runs one census or pairs invocation: reads the trace, refuses any set other than
/// <c>debug</c>/<c>batch</c> (D-029), classifies every <c>auto &amp;&amp; !correct</c> line,
/// writes the TSV to the output sink and the relation × site summary to the error sink.
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	/// <summary>TSV column order for the <c>census</c> subcommand (brief §4).</summary>
	public const string CensusHeader = "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";

	/// <summary>TSV column order for the <c>pairs</c> subcommand.</summary>
	public const string PairsHeader = "holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText";

	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongClassifier _classifier;
	private readonly TextWriter _output;
	private readonly TextWriter _error;

	/// <summary>Creates the runner.</summary>
	/// <param name="classifier">The relation/site classifier.</param>
	/// <param name="options">The bound CLI options.</param>
	/// <param name="output">TSV sink.</param>
	/// <param name="error">Summary/diagnostics sink.</param>
	public AutoWrongCensusRunner(AutoWrongClassifier classifier, AutoWrongCensusOptions options, TextWriter output, TextWriter error)
	{
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(output);
		ArgumentNullException.ThrowIfNull(error);
		_classifier = classifier;
		_output = output;
		_error = error;
	}

	/// <inheritdoc />
	public Task<int> RunAsync(CancellationToken cancellationToken)
	{
		ArgumentNullException.ThrowIfNull(cancellationToken);
		return Task.FromResult(Run(cancellationToken));
	}

	private int Run(CancellationToken cancellationToken)
	{
		var options = Options;
		if (string.IsNullOrEmpty(options.Command))
		{
			_error.WriteLine("unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
			return 1;
		}

		if (!File.Exists(options.TracePath))
		{
			_error.WriteLine($"trace file not found: {options.TracePath}");
			return 1;
		}

		var lines = ReadTrace(options.TracePath, out var readError);
		if (lines is null)
		{
			_error.WriteLine(readError);
			return 1;
		}

		var refused = lines.FirstOrDefault(l => !l.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !l.Set.Equals("batch", StringComparison.OrdinalIgnoreCase));
		if (refused is not null)
		{
			_error.WriteLine($"refused: trace set '{refused.Set}' is not debug or batch (D-029)");
			return 1;
		}

		return options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: RunPairs(options.CensusTsvPath, lines);
	}

	private AutoWrongCensusOptions Options { get; } = throw new InvalidOperationException("Options is set by the host factory after construction.");

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		_error.WriteLine($"autoWrongCensus set={lines.Count > 0 ? lines[0].Set : "?"} traceLines={lines.Count} autoWrongLines={autoWrong.Count}");

		_output.WriteLine(CensusHeader);

		var unknownSite = 0;
		var missingFields = new Dictionary<string, int>(StringComparer.Ordinal);
		var tierDirection = new Dictionary<string, int>(StringComparer.Ordinal);
		var overrideKeyHits = 0;
		var overrideSiteLines = 0;
		var reuseLines = 0;
		var reuseShouldReuseFalse = 0;
		var relationSite = new Dictionary<(string, string), int>(StringComparer.Ordinal);

		foreach (var line in autoWrong)
		{
			var result = _classifier.Classify(line);
			cancellationToken.ThrowIfCancellationRequested();

			if (result.Site.Length == 0)
			{
				unknownSite++;
				_error.WriteLine($"unknown atom path '{line.Atoms.Count > 0 ? line.Atoms[0].Path : "<none>"}' on {line.HoldoutId}#{line.LineIndex}");
				continue;
			}

			_output.WriteLine(string.Join('\t',
				Sanitize(result.HoldoutId),
				result.LineIndex.ToString(CultureInfo.InvariantCulture),
				Sanitize(result.Set),
				Sanitize(result.Relation),
				Sanitize(result.Site),
				Sanitize(result.OverrideKey),
				Sanitize(result.AcceptedTier),
				Sanitize(result.KeyTier),
				Sanitize(result.AcceptedState),
				Sanitize(result.KeyState),
				Sanitize(result.ParsedName),
				Sanitize(result.KeyHead),
				Sanitize(result.AcceptedDesc),
				Sanitize(result.KeyDesc),
				Sanitize(result.RawText)));

			var cell = (result.Relation, result.Site);
			relationSite[cell] = relationSite.GetValueOrDefault(cell) + 1;

			if (result.MissingField is not null)
			{
				missingFields[result.MissingField] = missingFields.GetValueOrDefault(result.MissingField) + 1;
			}

			if (result.Site == AutoWrongClassifier.SiteOverride)
			{
				overrideSiteLines++;
				if (result.OverrideKey == "yes")
				{
					overrideKeyHits++;
				}
			}

			if (result.Site == AutoWrongClassifier.SiteReuse)
			{
				reuseLines++;
				var atom = ChooseAtom(line);
				if (atom.LinkedIngredientId is not null
					&& !IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					reuseShouldReuseFalse++;
				}
			}

			if (result.Relation == AutoWrongClassifier.RelationRowChoiceTier)
			{
				var direction = TierRank(result.KeyTier) > TierRank(result.AcceptedTier) ? "key higher" : "accepted higher";
				tierDirection[direction] = tierDirection.GetValueOrDefault(direction) + 1;
			}

			if (result.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier)
			{
				_error.WriteLine($"same-head-other-qualifier {line.HoldoutId}#{line.LineIndex} key=[{string.Join(' ', result.KeyOnlyQualifiers ?? [])}] accepted=[{string.Join(' ', result.AcceptedOnlyQualifiers ?? [])}]");
			}
		}

		_error.WriteLine("relation\tsite\tcount");
		foreach (var (cell, count) in relationSite.OrderByDescending(kv => kv.Value).ThenBy(kv => kv.Key.Item1).ThenBy(kv => kv.Key.Item2))
		{
			_error.WriteLine($"{cell.Item1}\t{cell.Item2}\t{count}");
		}

		var otherCount = relationSite.Where(kv => kv.Key.Item1 == AutoWrongClassifier.RelationOther).Sum(kv => kv.Value);
		_error.WriteLine($"relation other: {otherCount}/{autoWrong.Count} ({(autoWrong.Count > 0 ? otherCount * 100.0 / autoWrong.Count : 0.0):F1}%)");
		_error.WriteLine($"missing fields: {(missingFields.Count == 0 ? "none" : string.Join(", ", missingFields.Select(kv => $"{kv.Key}={kv.Value}")))}");
		_error.WriteLine($"override-site lines: {overrideSiteLines}, exact-overrides.json raw-key hits: {overrideKeyHits}");
		_error.WriteLine($"reuse-site lines: {reuseLines}, ShouldReuse(parsedName, linkedIngredientId) false: {reuseShouldReuseFalse}");
		if (tierDirection.Count > 0)
		{
			_error.WriteLine($"row-choice-tier: {string.Join(", ", tierDirection.Select(kv => $"{kv.Key}={kv.Value}"))}");
		}

		return unknownSite > 0 ? 1 : 0;
	}

	private int RunPairs(string censusTsvPath, IReadOnlyList<TraceLine> lines)
	{
		if (!File.Exists(censusTsvPath))
		{
			_error.WriteLine($"census tsv not found: {censusTsvPath}");
			return 1;
		}

		var rows = File.ReadAllLines(censusTsvPath);
		if (rows.Length == 0)
		{
			_error.WriteLine($"census tsv is empty: {censusTsvPath}");
			return 1;
		}

		var header = rows[0].Split('\t');
		var idCol = Array.IndexOf(header, "holdoutId");
		var idxCol = Array.IndexOf(header, "lineIndex");
		var blockerCol = Array.IndexOf(header, "blocker");
		var routeCol = Array.IndexOf(header, "route");
		if (idCol < 0 || idxCol < 0 || blockerCol < 0 || routeCol < 0)
		{
			_error.WriteLine($"census tsv is missing a required column (holdoutId/lineIndex/blocker/route): {censusTsvPath}");
			return 1;
		}

		var wanted = new HashSet<(string, int)>(StringComparer.Ordinal);
		for (var i = 1; i < rows.Length; i++)
		{
			var cells = rows[i].Split('\t');
			if (cells.Length <= Math.Max(idCol, Math.Max(idxCol, Math.Max(blockerCol, routeCol))))
			{
				continue;
			}

			if (cells[blockerCol].Equals("window", StringComparison.OrdinalIgnoreCase)
				&& (cells[routeCol].Equals("compound", StringComparison.OrdinalIgnoreCase) || cells[routeCol].Equals("other", StringComparison.OrdinalIgnoreCase))
				&& int.TryParse(cells[idxCol], NumberStyles.Integer, CultureInfo.InvariantCulture, out var lineIndex))
			{
				wanted.Add((cells[idCol], lineIndex));
			}
		}

		var byKey = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		_output.WriteLine(PairsHeader);

		var emitted = 0;
		var missing = 0;
		foreach (var (holdoutId, lineIndex) in wanted.OrderBy(k => k.Item1).ThenBy(k => k.Item2))
		{
			if (!byKey.TryGetValue((holdoutId, lineIndex), out var line))
			{
				missing++;
				_error.WriteLine($"no trace line for {holdoutId}#{lineIndex}");
				continue;
			}

			var atom = ChooseAtom(line);
			var parsedNameHead = string.Join(' ', _classifier.KeyHeadPhrase(_normalizerTokens(atom.ParsedName)));
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(_normalizerTokens(First(line.ExpectedDescriptions))));
			_output.WriteLine(string.Join('\t',
				Sanitize(holdoutId),
				lineIndex.ToString(CultureInfo.InvariantCulture),
				Sanitize(parsedNameHead),
				Sanitize(keyHead),
				Sanitize(line.RawText)));
			emitted++;
		}

		_error.WriteLine($"pairs: window compound/other rows={wanted.Count} emitted={emitted} missingFromTrace={missing}");
		return missing > 0 ? 1 : 0;
	}

	private IReadOnlyList<string> _normalizerTokens(string text) => _normalizer.NormalizeToTokens(text);

	private readonly FdcNormalizer _normalizer;

	private static TraceAtom ChooseAtom(TraceLine line)
	{
		foreach (var atom in line.Atoms)
		{
			if (atom.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return line.Atoms[0];
	}

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static IReadOnlyList<TraceLine>? ReadTrace(string path, out string error)
	{
		var lines = new List<TraceLine>();
		try
		{
			foreach (var raw in File.ReadLines(path))
			{
				if (string.IsNullOrWhiteSpace(raw))
				{
					continue;
				}

				var line = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
				if (line is null)
				{
					error = $"trace line is not a JSON object: {path}";
					return null;
				}

				lines.Add(line);
			}
		}
		catch (JsonException ex)
		{
			error = $"trace file is not valid JSONL: {path} ({ex.Message})";
			return null;
		}

		error = string.Empty;
		return lines;
	}
}
