{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// The census runner: reads one HoldoutGate trace, classifies every <c>auto &amp;&amp; !correct</c>
/// line, and writes the TSV to <see cref="OutputWriters.Output"/> with the relation × site summary
/// on <see cref="OutputWriters.Error"/>. Refuses any trace whose records are not <c>debug</c> or
/// <c>batch</c> (D-029: no sealed read).
/// </summary>
public sealed class AutoWrongCensusRunner(
	IOptions<AutoWrongCensusOptions> options,
	AutoWrongClassifier classifier,
	OutputWriters writers) : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongCensusOptions _options = options.Value;

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.Command))
		{
			writers.Error.WriteLine("unusable arguments; expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'");
			return 1;
		}

		if (!File.Exists(_options.TracePath))
		{
			writers.Error.WriteLine($"trace file not found: {_options.TracePath}");
			return 1;
		}

		var lines = await ReadTraceAsync(_options.TracePath, cancellationToken).ConfigureAwait(false);
		if (lines is null)
		{
			return 1;
		}

		var refused = lines.Select(l => l.Set).Distinct(StringComparer.Ordinal).FirstOrDefault(s => s is not ("debug" or "batch"));
		if (refused is not null)
		{
			writers.Error.WriteLine($"refused: trace set '{refused}' is not debug or batch (D-029: no sealed read)");
			return 1;
		}

		return _options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase)
			? RunCensus(lines)
			: await RunPairsAsync(lines, cancellationToken).ConfigureAwait(false);
	}

	private int RunCensus(IReadOnlyList<TraceLine> lines)
	{
		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToList();
		var results = new List<ClassificationResult>(autoWrong.Count);

		foreach (var line in autoWrong)
		{
			var result = classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				writers.Error.WriteLine($"refused: unknown atom path '{line.Atoms.FirstOrDefault()?.Path}' on {line.HoldoutId}#{line.LineIndex}");
				return 1;
			}

			results.Add(result);
		}

		WriteCensusTsv(results);
		WriteSummary(results, lines.Count);
		return 0;
	}

	private async Task<int> RunPairsAsync(IReadOnlyList<TraceLine> lines, CancellationToken cancellationToken)
	{
		if (!File.Exists(_options.CensusTsvPath))
		{
			writers.Error.WriteLine($"census tsv not found: {_options.CensusTsvPath}");
			return 1;
		}

		var rows = await Task.Run(() => File.ReadAllLines(_options.CensusTsvPath), cancellationToken).ConfigureAwait(false);
		if (rows.Length == 0)
		{
			writers.Error.WriteLine($"census tsv is empty: {_options.CensusTsvPath}");
			return 1;
		}

		var header = rows[0].Split('\t');
		var indexOf = new Dictionary<string, int>(StringComparer.Ordinal);
		for (var i = 0; i < header.Length; i++)
		{
			indexOf[header[i]] = i;
		}

		foreach (var column in new[] { "holdoutId", "lineIndex", "blocker", "route" })
		{
			if (!indexOf.ContainsKey(column))
			{
				writers.Error.WriteLine($"census tsv is missing column '{column}': {_options.CensusTsvPath}");
				return 1;
			}
		}

		var byLine = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		writers.Output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var emitted = 0;
		for (var i = 1; i < rows.Length; i++)
		{
			var cells = rows[i].Split('\t');
			if (cells.Length < header.Length)
			{
				continue;
			}

			if (!cells[indexOf["blocker"]].Equals("window", StringComparison.Ordinal)
				|| (!cells[indexOf["route"]].Equals("compound", StringComparison.Ordinal) && !cells[indexOf["route"]].Equals("other", StringComparison.Ordinal)))
			{
				continue;
			}

			var holdoutId = cells[indexOf["holdoutId"]];
			if (!int.TryParse(cells[indexOf["lineIndex"]], out var lineIndex) || !byLine.TryGetValue((holdoutId, lineIndex), out var line))
			{
				writers.Error.WriteLine($"pairs: census row {holdoutId}#{lineIndex} not found in the trace");
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null
				? string.Empty
				: string.Join(' ', classifier.KeyHeadPhrase(_normalizerTokens(atom.ParsedName)));
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', classifier.KeyHeadPhrase(_normalizerTokens(keyDesc)));

			writers.Output.WriteLine($"{Sanitize(holdoutId)}\t{lineIndex}\t{Sanitize(parsedNameHead)}\t{Sanitize(keyHead)}\t{Sanitize(line.RawText)}");
			emitted++;
		}

		writers.Error.WriteLine($"pairs: emitted {emitted} window compound/other rows");
		return 0;
	}

	private void WriteCensusTsv(IReadOnlyList<ClassificationResult> results)
	{
		writers.Output.WriteLine("holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText");
		foreach (var r in results)
		{
			writers.Output.WriteLine(string.Join('\t',
				Sanitize(r.HoldoutId),
				r.LineIndex.ToString(),
				Sanitize(r.Set),
				Sanitize(r.Relation),
				Sanitize(r.Site),
				Sanitize(r.OverrideKey),
				Sanitize(r.AcceptedTier),
				Sanitize(r.KeyTier),
				Sanitize(r.AcceptedState),
				Sanitize(r.KeyState),
				Sanitize(r.ParsedName),
				Sanitize(r.KeyHead),
				Sanitize(r.AcceptedDesc),
				Sanitize(r.KeyDesc),
				Sanitize(r.RawText)));
		}
	}

	private void WriteSummary(IReadOnlyList<ClassificationResult> results, int tracedLines)
	{
		var sets = string.Join(",", results.Select(r => r.Set).Distinct(StringComparer.Ordinal).OrderBy(s => s, StringComparer.Ordinal));
		writers.Error.WriteLine($"autoWrongCensus set={sets} traced={tracedLines} autoWrong={results.Count}");

		foreach (var (relation, site, count) in results
			.GroupBy(r => (r.Relation, r.Site))
			.Select(g => (g.Key.Relation, g.Key.Site, g.Count()))
			.OrderBy(t => t.Relation, StringComparer.Ordinal)
			.ThenBy(t => t.Site, StringComparer.Ordinal))
		{
			writers.Error.WriteLine($"{relation}\t{site}\t{count}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		writers.Error.WriteLine($"other={other}/{results.Count} ({(results.Count > 0 ? other * 100.0 / results.Count : 0.0):F1}%)");

		var missing = results.Where(r => r.MissingField is not null)
			.GroupBy(r => r.MissingField!)
			.Select(g => $"{g.Key}={g.Count()}")
			.OrderBy(s => s, StringComparer.Ordinal);
		writers.Error.WriteLine($"missingFields: {(missing.Any() ? string.Join(" ", missing) : "none")}");

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		writers.Error.WriteLine($"overrideKey: yes={overrideLines.Count(r => r.OverrideKey == "yes")} no={overrideLines.Count(r => r.OverrideKey == "no")}");

		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		var reuseNameMismatch = 0;
		foreach (var r in reuseLines)
		{
			var line = FindLine(r);
			var atom = line?.Atoms.FirstOrDefault(a => a.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase)) ?? line?.Atoms.FirstOrDefault();
			if (atom is not null && !string.IsNullOrEmpty(atom.LinkedIngredientId))
			{
				if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(atom.ParsedName), atom.LinkedIngredientId))
				{
					reuseNameMismatch++;
				}
			}
		}

		writers.Error.WriteLine($"reuse site: lines={reuseLines.Count} shouldReuse(parsedName, linkedIngredientId)=false: {reuseNameMismatch}");

		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		writers.Error.WriteLine($"row-choice-tier: keyHigher={tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier))} acceptedHigher={tierLines.Count(r => TierRank(r.AcceptedTier) > TierRank(r.KeyTier))}");

		foreach (var r in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			writers.Error.WriteLine($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{string.Join(" ", r.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(" ", r.AcceptedOnlyQualifiers ?? [])}]");
		}
	}

	private TraceLine? _lastLine;

	private TraceLine? FindLine(ClassificationResult r) => _lastLine is { } l && l.HoldoutId == r.HoldoutId && l.LineIndex == r.LineIndex ? l : null;

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static IReadOnlyList<string> _normalizerTokens(string text) =>
		NormalizerHolder.Normalizer.NormalizeToTokens(text);

	private static class NormalizerHolder
	{
		public static FdcNormalizer Normalizer { get; } = new();
	}

	private static async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(string path, CancellationToken cancellationToken)
	{
		var lines = new List<TraceLine>();
		try
		{
			await foreach (var raw in File.ReadLinesAsync(path, cancellationToken).ConfigureAwait(false))
			{
				if (string.IsNullOrWhiteSpace(raw))
				{
					continue;
				}

				var line = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
				if (line is null)
				{
					writers.Error.WriteLine($"refused: unparseable trace line in {path}");
					return null;
				}

				lines.Add(line);
			}
		}
		catch (JsonException ex)
		{
			writers.Error.WriteLine($"refused: malformed JSON in {path}: {ex.Message}");
			return null;
		}

		return lines;
	}
}
